import{_ as s,C as n,c as a,o as i,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Manage products","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/products-prices/manage-products.md","filePath":"master/sales/sales/products-prices/manage-products.md","lastUpdated":1792041590000}'),l={name:"master/sales/sales/products-prices/manage-products.md"};function g(c,e,d,u,h,p){const o=n("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="manage-products" tabindex="-1">Manage products <a class="header-anchor" href="#manage-products" aria-label="Permalink to &quot;Manage products&quot;">​</a></h1><p>A product is any good or service you sell. You pick products when you build a quotation. The product holds the price, the cost, the taxes and the invoice policy that the order line uses.</p><blockquote><p><strong>In simple words:</strong> A product is a record of what you sell and what it costs.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Some fields depend on settings. Go to <code>Sales → Settings → Manage Products</code> and turn on the options you need:</p><ul><li><strong>Variants:</strong> Allow products to have multiple variants.</li><li><strong>Unit of Measure:</strong> Allow products to have a unit of measure.</li><li><strong>Packagings:</strong> Allow products to have multiple packagings.</li><li><strong>Price Lists:</strong> Allow products to be sold at prices set by a price list.</li></ul>',6)),r(o,{src:"/images1/sales/set_products.png",alt:"Manage Products settings page showing Variants, Unit of Measure, Packagings and Price Lists"}),e[1]||(e[1]=t('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Go to <code>Sales → Products</code>. The list has these views:</p><ul><li><strong>Default:</strong> All products.</li><li><strong>Goods:</strong> Products of type <strong>Goods</strong>.</li><li><strong>Services:</strong> Products of type <strong>Service</strong>.</li><li><strong>Favorites:</strong> Products you marked as favorite.</li><li><strong>Archived:</strong> Archived products.</li><li><strong>Inventory Management</strong> and <strong>Components:</strong> Extra views for stock and component products.</li></ul><p>The list shows <strong>Favorite</strong>, <strong>Images</strong>, <strong>Name</strong>, <strong>Variants</strong>, <strong>Reference</strong>, <strong>Tags</strong>, <strong>Price</strong>, <strong>Cost</strong>, <strong>On Hand</strong> and <strong>Forecasted</strong>. Use <strong>Group by</strong> for <strong>Type</strong>, <strong>Category</strong> or <strong>Created At</strong>.</p>',4)),r(o,{src:"/images1/sales/products_list.png",alt:"Products list with the Default, Goods, Services, Favorites and Archived views and the New Product button"}),e[2]||(e[2]=t('<h2 id="create-a-product" tabindex="-1">Create a product <a class="header-anchor" href="#create-a-product" aria-label="Permalink to &quot;Create a product&quot;">​</a></h2><ol><li>Go to <code>Sales → Products</code>.</li><li>Click <strong>New Product</strong>.</li><li>Fill in the form, as described below.</li><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong> to save and start a new product.</li></ol>',2)),r(o,{src:"/images1/sales/product_form.png",alt:"New Product form, full page"}),e[3]||(e[3]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> Enter the product name. This field is required.</li><li><strong><em>Description:</em></strong> Add a description with the text editor.</li><li><strong><em>Tags:</em></strong> Choose one or more tags. See <a href="./../configuration/tags.html">Tags</a>.</li><li><strong><em>Images:</em></strong> Drag and drop files, or click <strong>Browse</strong>.</li></ul><h3 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h3><p>This section shows for products of type <strong>Goods</strong>.</p><ul><li><strong><em>Track Inventory:</em></strong> Turn on to track stock for this product.</li><li><strong><em>Track By:</em></strong> Choose <strong>By Unique Serial Number</strong>, <strong>By Lots</strong> or <strong>By Quantity</strong>. It shows only when lots and serial numbers are enabled in Inventory.</li></ul><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><ul><li><strong><em>Routes:</em></strong> Choose how the product is supplied, for example by purchasing or manufacturing. The routes depend on the modules you installed.</li></ul><h3 id="logistics" tabindex="-1">Logistics <a class="header-anchor" href="#logistics" aria-label="Permalink to &quot;Logistics&quot;">​</a></h3><ul><li><strong><em>Responsible:</em></strong> Choose the user who is responsible for the product.</li><li><strong><em>Weight:</em></strong> Enter the weight.</li><li><strong><em>Volume:</em></strong> Enter the volume.</li><li><strong><em>Customer Lead Time (Days):</em></strong> Enter the promised days between order confirmation and delivery.</li></ul><h3 id="invoice-policy" tabindex="-1">Invoice policy <a class="header-anchor" href="#invoice-policy" aria-label="Permalink to &quot;Invoice policy&quot;">​</a></h3><ul><li><strong><em>Invoice Policy:</em></strong> Choose <strong>Ordered Quantities</strong> or <strong>Delivered Quantities</strong>. See <a href="./../invoicing/invoicing-policies.html">Invoicing policies</a>.</li></ul><h3 id="account-properties" tabindex="-1">Account properties <a class="header-anchor" href="#account-properties" aria-label="Permalink to &quot;Account properties&quot;">​</a></h3><ul><li><strong><em>Income Account:</em></strong> The account used when you validate a customer invoice. The default is <strong>Product Sales</strong>.</li><li><strong><em>Expense Account:</em></strong> The account used for the cost of the product. The default is <strong>Expenses</strong>.</li></ul><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong><em>Type:</em></strong> Choose <strong>Goods</strong> or <strong>Service</strong>.</li><li><strong><em>Reference:</em></strong> Enter an internal code for the product.</li><li><strong><em>Barcode:</em></strong> Enter the barcode.</li><li><strong><em>Category:</em></strong> Choose a category. This field is required. The default is <strong>All</strong>. See <a href="./../configuration/product-categories.html">Product categories</a>.</li><li><strong><em>Company:</em></strong> Choose a company, or keep <strong>All Companies</strong>.</li></ul><h3 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h3><ul><li><strong><em>Price:</em></strong> The selling price. This field is required.</li><li><strong><em>Uom id:</em></strong> The unit of measure for the price. The default is <strong>Units</strong>.</li><li><strong><em>Cost:</em></strong> The purchase cost. This field is required.</li><li><strong><em>Uom po id:</em></strong> The unit of measure for purchasing. The default is <strong>Units</strong>.</li><li><strong><em>Product taxes:</em></strong> Choose the taxes that apply when you sell.</li><li><strong><em>Supplier taxes:</em></strong> Choose the taxes that apply when you buy.</li></ul>',17)),r(o,{src:"/images1/sales/product_form_pricing.png",alt:"Product form, Settings and Pricing sections"}),e[4]||(e[4]=t('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Units of measure are covered in <a href="./../configuration/uom-categories.html">UoM categories</a>.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>After you click <strong>Create</strong>, the app opens the product. From there you can:</p><ul><li><strong>Edit:</strong> Change the product details.</li><li><strong>Print Labels:</strong> Enter <strong>Number of Labels</strong> and choose a <strong>Format</strong>, such as <strong>2x7 with price</strong> or <strong>4x12</strong>.</li><li><strong>Delete:</strong> Remove the product.</li></ul><p>If <strong>Variants</strong> is on, the product also has <strong>Attributes</strong> and <strong>Variants</strong> pages. See <a href="./product-variants.html">Product variants</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./product-variants.html">Product variants</a></li><li><a href="./price-lists.html">Price lists</a></li><li><a href="./../invoicing/invoicing-policies.html">Invoicing policies</a></li><li><a href="./../quotations-orders/create-quotation.html">Create a quotation</a></li></ul>',7))])}const _=s(l,[["render",g]]);export{f as __pageData,_ as default};
